targets.rawSql:
SELECT toStartOfDay(ts) AS time,
       if(countIf(fam = 'Opus') = 0, NULL, round(avgIf(ttft_ms, fam = 'Opus'))) AS Opus,
       if(countIf(fam = 'Sonnet') = 0, NULL, round(avgIf(ttft_ms, fam = 'Sonnet'))) AS Sonnet,
       if(countIf(fam = 'Haiku') = 0, NULL, round(avgIf(ttft_ms, fam = 'Haiku'))) AS Haiku,
       if(countIf(fam = 'Other') = 0, NULL, round(avgIf(ttft_ms, fam = 'Other'))) AS Other
FROM
(
    SELECT ts, ttft_ms, multiIf(positionCaseInsensitive(model, 'opus') > 0, 'Opus', positionCaseInsensitive(model, 'sonnet') > 0, 'Sonnet', positionCaseInsensitive(model, 'haiku') > 0, 'Haiku', 'Other') AS fam
    FROM cc.api_requests WHERE ttft_ms > 0 AND ('__all' IN (${account:singlequote}) OR account_uuid IN (${account:singlequote})) AND ('${project}' = '__all' OR project = '${project}') AND ('${session}' = '__all' OR session_id = '${session}') AND ('${actor}' = '__all' OR actor = '${actor}') AND ('${skill}' = '__all' OR skill = '${skill}') AND $__timeFilter(ts)
)
GROUP BY time ORDER BY time
